    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.75rem;
      width: min(100%, 360px);
    }

    .time-box {
      text-align: center;
      padding: 0.75rem 0.5rem;
