      border: 1px solid rgba(141, 211, 255, 0.12);
      position: relative;
      overflow: hidden;
    }

    .editorial-feature .feature-visual::before {
      content: "";
      position: absolute;
      inset: 12% 12% auto auto;
      width: 44%;
      aspect-ratio: 1;
      border-radius: 50%;
      background: radial-gradient(circle at 35% 35%, rgba(255, 255, 255, 0.22), transparent 50%);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    footer {
      padding: 1rem 0 2.5rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      padding-top: 1.25rem;
      border-top: 1px solid rgba(141, 211, 255, 0.12);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 1080px) {
      .hero,
      .deal-grid,
      .story-grid {
        grid-template-columns: 1fr;
      }

      .product-grid {
