      transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, color 160ms ease;
    }

    .icon-button {
      display: inline-grid;
      place-items: center;
      width: 2.75rem;
      height: 2.75rem;
      background: var(--surface);
      color: var(--text);
      border-color: var(--border);
    }

    .primary-button {
      background: linear-gradient(135deg, var(--accent-strong), #7a5cff);
      color: #06111a;
      padding: 0.95rem 1.25rem;
      box-shadow: 0 16px 30px rgba(76, 181, 255, 0.18);
    }

    .secondary-button,
    .filter-button {
      background: var(--surface);
      color: var(--text);
      border-color: var(--border);
      padding: 0.9rem 1.15rem;
    }

    .icon-button:hover,
    .primary-button:hover,
    .secondary-button:hover,
    .filter-button:hover {
      transform: translateY(-1px);
    }

    main {
      padding: 1.5rem 0 4rem;
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
      gap: 1.5rem;
      align-items: stretch;
      padding: 2rem 0 2.75rem;
    }

    .hero-copy,
    .hero-panel,
    .section-card,
    .promo-card,
    .story-card,
    .product-card {
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.01));
      border: 1px solid rgba(141, 211, 255, 0.12);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      border-radius: var(--radius-xl);
      padding: clamp(1.5rem, 2.8vw, 3rem);
      background:
        radial-gradient(circle at top right, rgba(76, 181, 255, 0.18), transparent 28%),
        linear-gradient(180deg, rgba(22, 32, 45, 0.98), rgba(15, 22, 32, 0.98));
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
      padding: 0.45rem 0.8rem;
      border-radius: 999px;
      background: rgba(125, 226, 184, 0.12);
      color: var(--success);
      font-size: 0.92rem;
      font-weight: 600;
      letter-spacing: 0.02em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 0.55rem;
      height: 0.55rem;
      border-radius: 50%;
      background: currentColor;
      box-shadow: 0 0 0 6px rgba(125, 226, 184, 0.12);
    }

    h1 {
      margin: 1rem 0 0;
      font-size: clamp(2.4rem, 6vw, 5rem);
      line-height: 0.96;
      letter-spacing: -0.04em;
      max-width: 10ch;
    }

    .hero-copy p {
      max-width: 62ch;
      margin: 1.1rem 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      margin-top: 1.6rem;
    }

    .hero-meta {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.85rem;
      margin-top: 1.6rem;
    }

    .metric {
      padding: 1rem;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.02);
      border: 1px solid rgba(141, 211, 255, 0.1);
      min-width: 0;
    }

    .metric strong {
      display: block;
      font-size: 1.2rem;
      letter-spacing: -0.02em;
    }

    .metric span {
      color: var(--muted);
      font-size: 0.92rem;
    }

    .hero-panel {
      border-radius: var(--radius-xl);
      padding: 1.2rem;
      display: grid;
      gap: 1rem;
      grid-template-rows: auto 1fr;
      background:
        linear-gradient(180deg, rgba(21, 28, 40, 0.98), rgba(18, 24, 34, 0.98));
    }

    .panel-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .live-pill {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.4rem 0.7rem;
      border-radius: 999px;
      background: rgba(141, 211, 255, 0.1);
      color: var(--accent);
      font-size: 0.88rem;
      font-weight: 600;
    }

    .live-pill::before {
      content: "";
      width: 0.55rem;
      height: 0.55rem;
      border-radius: 50%;
      background: currentColor;
      box-shadow: 0 0 0 7px rgba(141, 211, 255, 0.12);
    }

    .hero-feature {
      border-radius: 24px;
      overflow: clip;
      min-height: 100%;
      background:
        radial-gradient(circle at 20% 20%, rgba(243, 179, 106, 0.32), transparent 30%),
        radial-gradient(circle at 80% 25%, rgba(76, 181, 255, 0.24), transparent 26%),
        linear-gradient(180deg, #1d2939 0%, #101822 100%);
      border: 1px solid rgba(141, 211, 255, 0.14);
      position: relative;
      padding: 1.35rem;
      display: grid;
      align-content: end;
      gap: 0.85rem;
      min-height: 420px;
    }

    .hero-feature::before,
    .hero-feature::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 999px;
      pointer-events: none;
    }

    .hero-feature::before {
      width: 210px;
      height: 210px;
      right: -42px;
      top: -30px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: inset 0 0 50px rgba(255, 255, 255, 0.05);
    }

    .hero-feature::after {
      width: 150px;
      height: 150px;
      left: 18px;
      bottom: 18px;
      border: 1px solid rgba(125, 226, 184, 0.22);
    }

    .product-swatch {
      display: grid;
      place-items: center;
      width: 100%;
      aspect-ratio: 4 / 3;
      border-radius: 22px;
      background:
        linear-gradient(140deg, rgba(255, 255, 255, 0.1), transparent 55%),
        linear-gradient(180deg, #233247, #131c28);
      border: 1px solid rgba(255, 255, 255, 0.08);
      position: relative;
      overflow: hidden;
    }

    .product-swatch::before {
      content: "";
      position: absolute;
      inset: 12% auto auto 14%;
      width: 42%;
      aspect-ratio: 1;
      border-radius: 36% 64% 40% 60% / 42% 40% 60% 58%;
      background: linear-gradient(180deg, rgba(141, 211, 255, 0.34), rgba(76, 181, 255, 0.08));
      filter: blur(2px);
    }

    .product-swatch::after {
      content: "";
      position: absolute;
      inset: auto 16% 16% auto;
      width: 30%;
      aspect-ratio: 1;
      border-radius: 30% 70% 61% 39% / 48% 49% 51% 52%;
      background: linear-gradient(180deg, rgba(243, 179, 106, 0.28), rgba(243, 179, 106, 0.05));
    }

    .swatch-label {
      position: relative;
      z-index: 1;
      display: inline-grid;
      gap: 0.45rem;
      place-items: center;
      text-align: center;
      padding: 1rem;
      max-width: 16ch;
    }

    .swatch-label strong {
      font-size: 1.5rem;
      line-height: 1;
      letter-spacing: -0.03em;
    }

    .swatch-label span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .section {
      padding-top: 1rem;
    }

    .section-heading {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      margin-bottom: 1rem;
    }

    .section-heading h2 {
      margin: 0;
      font-size: clamp(1.5rem, 3vw, 2.2rem);
      letter-spacing: -0.03em;
    }

    .section-heading p {
      margin: 0;
      color: var(--muted);
      max-width: 54ch;
    }

    .filter-bar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
      margin: 1.25rem 0 1.25rem;
    }

    .filter-button[aria-pressed="true"] {
      background: var(--accent);
      color: #07111a;
      border-color: transparent;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      border-radius: var(--radius-lg);
      padding: 1rem;
      display: grid;
      gap: 0.9rem;
      min-width: 0;
      background:
        radial-gradient(circle at top left, rgba(141, 211, 255, 0.08), transparent 28%),
        linear-gradient(180deg, rgba(18, 24, 34, 0.98), rgba(22, 29, 41, 0.98));
    }

    .product-card h3,
    .story-card h3,
    .promo-card h3 {
      margin: 0;
      letter-spacing: -0.02em;
    }

    .product-card p,
    .story-card p,
    .promo-card p {
      margin: 0;
      color: var(--muted);
      min-width: 0;
      overflow-wrap: anywhere;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 0.75rem;
      padding-top: 0.1rem;
    }

    .price {
      font-size: 1.15rem;
      font-weight: 700;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      width: fit-content;
      padding: 0.36rem 0.7rem;
      border-radius: 999px;
      background: rgba(243, 179, 106, 0.12);
      color: #ffd6ae;
      font-size: 0.82rem;
      font-weight: 600;
    }

    .deal-grid {
      display: grid;
      grid-template-columns: 1.3fr 0.7fr;
      gap: 1rem;
    }

    .section-card {
      border-radius: var(--radius-xl);
      padding: 1.2rem;
      background:
        linear-gradient(135deg, rgba(76, 181, 255, 0.12), transparent 30%),
        linear-gradient(180deg, rgba(17, 24, 35, 0.98), rgba(14, 20, 30, 0.98));
    }

    .promo-band {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1rem;
      align-items: center;
      padding: 1.2rem;
      border-radius: 22px;
      background: linear-gradient(135deg, rgba(141, 211, 255, 0.14), rgba(125, 226, 184, 0.08));
      border: 1px solid rgba(141, 211, 255, 0.18);
      margin-bottom: 1rem;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.75rem;
      width: min(100%, 360px);
    }

    .time-box {
      text-align: center;
      padding: 0.75rem 0.5rem;
      border-radius: 16px;
      background: rgba(7, 12, 18, 0.45);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .time-box strong {
      display: block;
      font-size: 1.5rem;
      line-height: 1;
    }

    .time-box span {
      color: var(--muted);
      font-size: 0.8rem;
    }

    .deal-cards {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .promo-card,
    .story-card {
      border-radius: var(--radius-lg);
      padding: 1rem;
      min-width: 0;
      background: linear-gradient(180deg, rgba(24, 32, 44, 0.96), rgba(17, 23, 33, 0.98));
    }

    .promo-card {
      display: grid;
      gap: 0.9rem;
    }

    .promo-card .tag,
    .story-card .tag {
      width: fit-content;
    }

    .story-grid {
      display: grid;
      grid-template-columns: 0.85fr 1.15fr;
      gap: 1rem;
    }

    .story-list {
      display: grid;
      gap: 1rem;
    }

    .story-card {
      display: grid;
      grid-template-columns: 1fr 112px;
      gap: 1rem;
      align-items: center;
    }

    .story-card aside {
      width: 112px;
      height: 112px;
      border-radius: 20px;
      background:
        radial-gradient(circle at 30% 30%, rgba(125, 226, 184, 0.34), transparent 35%),
        radial-gradient(circle at 70% 70%, rgba(243, 179, 106, 0.32), transparent 32%),
        linear-gradient(180deg, #1b2634, #111824);
      border: 1px solid rgba(141, 211, 255, 0.12);
    }

    .editorial-feature {
      display: grid;
      align-content: end;
      gap: 0.85rem;
      min-height: 100%;
      background:
        radial-gradient(circle at top right, rgba(243, 179, 106, 0.12), transparent 30%),
        linear-gradient(180deg, rgba(24, 30, 42, 0.98), rgba(15, 21, 31, 0.98));
      border-radius: var(--radius-xl);
      padding: 1.35rem;
    }

    .editorial-feature .feature-visual {
      min-height: 320px;
      border-radius: 24px;
      background:
        linear-gradient(135deg, rgba(125, 226, 184, 0.16), transparent 35%),
        linear-gradient(225deg, rgba(76, 181, 255, 0.26), transparent 35%),
        linear-gradient(180deg, #223245, #101722);
      border: 1px solid rgba(141, 211, 255, 0.12);
      position: relative;
      overflow: hidden;
    }

    .editorial-feature .feature-visual::before {
      content: "";
      position: absolute;
      inset: 12% 12% auto auto;
      width: 44%;
      aspect-ratio: 1;
      border-radius: 50%;
      background: radial-gradient(circle at 35% 35%, rgba(255, 255, 255, 0.22), transparent 50%);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    footer {
      padding: 1rem 0 2.5rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      padding-top: 1.25rem;
      border-top: 1px solid rgba(141, 211, 255, 0.12);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 1080px) {
      .hero,
      .deal-grid,
      .story-grid {
        grid-template-columns: 1fr;
      }

      .product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .hero-feature {
        min-height: 360px;
      }
    }

    @media (max-width: 720px) {
      .header-inner {
        flex-wrap: wrap;
      }

      nav {
        width: 100%;
        order: 3;
      }

      nav ul {
        justify-content: flex-start;
      }

      .hero-meta,
      .deal-cards {
        grid-template-columns: 1fr;
      }

      .product-grid,
      .countdown {
        grid-template-columns: 1fr;
      }

      .story-card {
        grid-template-columns: 1fr;
      }

      .story-card aside {
        width: 100%;
        height: 150px;
      }

      .promo-band {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --bg-soft: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --border: ButtonBorder;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: Highlight;
        --accent-strong: Highlight;
      }

      body,
      header,
      .hero-copy,
      .hero-panel,
      .section-card,
      .promo-card,
      .story-card,
      .product-card,
      .editorial-feature,
      .icon-button,
      .secondary-button,
      .filter-button,
      .primary-button,
      .metric,
      .product-swatch,
      .hero-feature,
      .story-card aside,
      .feature-visual,
      .time-box {
        forced-color-adjust: auto;
        border-color: ButtonBorder;
        background: Canvas;
        color: CanvasText;
        box-shadow: none;
      }

      .skip-link {
        background: Highlight;
        color: HighlightText;
      }

      .filter-button[aria-pressed="true"],
      .primary-button {
        background: Highlight;
        color: HighlightText;
      }

      .eyebrow,
      .live-pill,
      .tag {
        border: 1px solid ButtonBorder;
        background: Canvas;
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header>
    <div class="shell header-inner">
      <a class="brand" href="#" aria-label="Northstar Supply home">
        <span class="brand-mark" aria-hidden="true">N</span>
        <span class="brand-name">Northstar Supply</span>
      </a>

      <nav aria-label="Primary">
        <ul>
          <li><a href="#featured">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
        </ul>
      </nav>

      <div class="utility" role="group" aria-label="Store actions">
        <button class="icon-button" type="button" aria-label="Search">
          <span aria-hidden="true">⌕</span>
        </button>
        <button class="icon-button" type="button" aria-label="Shopping bag">
          <span aria-hidden="true">🛍</span>
        </button>
      </div>
    </div>
  </header>

  <main id="main">
    <div class="shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <span class="eyebrow">New season retail edit</span>
          <h1 id="hero-title">Elevated essentials for everyday living.</h1>
          <p>
            Discover premium wardrobe staples, home upgrades, and limited-time offers curated for a modern
            retail customer.
          </p>
          <div class="hero-actions">
            <a class="primary-button" href="#featured">Shop featured products</a>
            <a class="secondary-button" href="#editorial">Read the style journal</a>
          </div>
          <div class="hero-meta" aria-label="Store highlights">
            <div class="metric">
              <strong>120+</strong>
              <span>new arrivals this week</span>
            </div>
            <div class="metric">
              <strong>2-day</strong>
              <span>delivery on select orders</span>
            </div>
            <div class="metric">
              <strong>Member</strong>
              <span>exclusive pricing on top picks</span>
            </div>
          </div>
        </div>

        <aside class="hero-panel" aria-label="Spotlight product">
          <div class="panel-top">
            <span class="live-pill">Just dropped</span>
            <span class="tag">Limited stock</span>
          </div>
          <div class="hero-feature">
            <div class="product-swatch" aria-hidden="true">
              <div class="swatch-label">
                <strong>Arc Chair</strong>
                <span>Textured boucle lounge seating</span>
              </div>
            </div>
            <div>
              <h2 style="margin: 0; font-size: 1.3rem; letter-spacing: -0.02em;">Soft form, strong presence.</h2>
              <p style="margin: 0.4rem 0 0; color: var(--muted);">
                The statement piece of the season pairs sculpted lines with durable comfort.
              </p>
            </div>
          </div>
        </aside>
      </section>

      <section id="featured" class="section" aria-labelledby="featured-title">
        <div class="section-heading">
          <div>
            <h2 id="featured-title">Featured products</h2>
            <p>Browse best-selling staples and newly launched pieces across apparel, accessories, and home.</p>
          </div>
        </div>

        <div class="filter-bar" role="toolbar" aria-label="Featured product filters">
          <button class="filter-button" type="button" aria-pressed="true" data-filter="trending">Trending</button>
          <button class="filter-button" type="button" aria-pressed="false" data-filter="new">New in</button>
          <button class="filter-button" type="button" aria-pressed="false" data-filter="essentials">Essentials</button>
        </div>

        <div class="product-grid" id="product-grid" aria-live="polite">
          <article class="product-card">
            <div class="product-swatch" aria-hidden="true">
              <div class="swatch-label">
                <strong>Cloud Knit</strong>
                <span>Merino blend crewneck</span>
              </div>
            </div>
            <span class="tag">Member favorite</span>
            <h3>Cloud Knit Crewneck</h3>
            <p>Lightweight warmth with a clean silhouette for layered dressing.</p>
            <div class="product-meta">
              <span class="price">$88</span>
              <a href="#deals">View offer</a>
            </div>
          </article>

          <article class="product-card">
            <div class="product-swatch" aria-hidden="true">
              <div class="swatch-label">
                <strong>Atlas Bag</strong>
                <span>Structured everyday carry</span>
              </div>
            </div>
            <span class="tag">Bestseller</span>
            <h3>Atlas Carryall</h3>
            <p>Roomy organization, polished hardware, and all-day durability.</p>
            <div class="product-meta">
              <span class="price">$124</span>
              <a href="#editorial">See styling</a>
            </div>
          </article>

          <article class="product-card">
            <div class="product-swatch" aria-hidden="true">
              <div class="swatch-label">
                <strong>Halo Lamp</strong>
                <span>Ambient brass accent</span>
              </div>
            </div>
            <span class="tag">Home upgrade</span>
            <h3>Halo Accent Lamp</h3>
            <p>Warm light and a compact profile designed for desks and bedside tables.</p>
            <div class="product-meta">
              <span class="price">$156</span>
              <a href="#deals">Bundle deal</a>
            </div>
          </article>

          <article class="product-card">
            <div class="product-swatch" aria-hidden="true">
              <div class="swatch-label">
                <strong>Pulse Sneaker</strong>
                <span>Street-ready comfort</span>
              </div>
            </div>
            <span class="tag">New arrival</span>
            <h3>Pulse Runner</h3>
            <p>Responsive cushioning and a minimalist upper for daily wear.</p>
            <div class="product-meta">
              <span class="price">$112</span>
              <a href="#editorial">Learn more</a>
            </div>
          </article>
        </div>
      </section>

      <section id="deals" class="section" aria-labelledby="deals-title">
        <div class="section-heading">
          <div>
            <h2 id="deals-title">Deals & limited offers</h2>
            <p>Time-sensitive savings on curated sets, seasonal essentials, and storewide favorites.</p>
          </div>
        </div>

        <div class="deal-grid">
          <article class="section-card">
            <div class="promo-band">
              <div>
                <span class="tag">Ends tonight</span>
                <h3 style="margin-top: 0.75rem; font-size: 1.5rem;">Extra 20% off home refresh bundles</h3>
                <p>Upgrade your space with coordinated lighting, storage, and textiles.</p>
              </div>
              <div class="countdown" aria-label="Promotion countdown">
                <div class="time-box"><strong data-countdown="days">08</strong><span>Days</span></div>
                <div class="time-box"><strong data-countdown="hours">14</strong><span>Hours</span></div>
                <div class="time-box"><strong data-countdown="minutes">26</strong><span>Minutes</span></div>
                <div class="time-box"><strong data-countdown="seconds">40</strong><span>Seconds</span></div>
              </div>
            </div>

            <div class="deal-cards">
              <article class="promo-card">
                <span class="tag">Bundle</span>
                <h3>Weekend layer set</h3>
                <p>Buy 2 knitwear pieces, save 15% at checkout.</p>
                <a href="#featured">Shop the set</a>
