      inset: 12% auto auto 14%;
      width: 42%;
      aspect-ratio: 1;
      border-radius: 36% 64% 40% 60% / 42% 40% 60% 58%;
      background: linear-gradient(180deg, rgba(141, 211, 255, 0.34), rgba(76, 181, 255, 0.08));
      filter: blur(2px);
