    .deal-grid {
      display: grid;
      grid-template-columns: 1.3fr 0.7fr;
      gap: 1rem;
    }

    .section-card {
      border-radius: var(--radius-xl);
      padding: 1.2rem;
      background:
        linear-gradient(135deg, rgba(76, 181, 255, 0.12), transparent 30%),
