    .promo-band {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1rem;
      align-items: center;
      padding: 1.2rem;
      border-radius: 22px;
      background: linear-gradient(135deg, rgba(141, 211, 255, 0.14), rgba(125, 226, 184, 0.08));
